class Solution:
    def wordPattern(self, pattern: str, s: str) -> bool:
        words = s.split()
        if len(pattern) != len(words):
            return False
        for i in range(len(pattern)):
            for j in range(i + 1, len(pattern)):
                if (pattern[i] == pattern[j]) != (words[i] == words[j]):
                    return False
        return True

